-- V72 — Cadastro antigo importado com segurança
-- Base: importacao_clientes_resumindo_viagens_consolidada_v3_contato_lider(1).xlsx
--
-- Regra de segurança:
-- 1. Se já existir cliente com o mesmo CPF em public.clients, o registro NÃO será inserido.
-- 2. Clientes importados entram na aba "Cadastro antigo".
-- 3. Eles NÃO entram automaticamente em "Processos em andamento" nem em "Processos concluídos".
-- 4. Depois da conferência no Admin, use "Remeter para concluídos" em cada cliente antigo.

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS legacy_import boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS legacy_import_batch text;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS visa_expiration_date date;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS passport_expiration_date date;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_video_call_scheduled boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_video_call_done boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_feedback_sent boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_feedback_answered boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_feedback_posted boolean DEFAULT false;

ALTER TABLE public.clients
ADD COLUMN IF NOT EXISTS stage_ready_to_archive boolean DEFAULT false;

