INSERT INTO public.clients (name, cpf, birth_date, phone, email, family_group, grupo_familiar_master, consulate_city, tipo_processo, is_renewal, visa_result, visa_expiration_date, passport_expiration_date, data_inicio_processo, casv_date, interview_date, video_call_date, passport_tracking_code, no_form_required, observacoes_gerais, notes, status, is_locked, is_completed, legacy_import, legacy_import_batch, stage_ds160_completed, stage_fee_generated, stage_fee_paid, stage_dates_scheduled, stage_video_call_scheduled, stage_video_call_done, stage_interview_done, stage_passport_returned, stage_feedback_sent, stage_feedback_answered, stage_feedback_posted, stage_ready_to_archive, access_token, created_at, updated_at)
SELECT
  r.name::text,
  r.cpf::text,
  r.birth_date::date,
  r.phone::text,
  r.email::text,
  r.family_group::text,
  r.grupo_familiar_master::boolean,
  r.consulate_city::text,
  r.tipo_processo::text,
  r.is_renewal::boolean,
  r.visa_result::text,
  r.visa_expiration_date::date,
  r.passport_expiration_date::date,
  r.data_inicio_processo::date,
  r.casv_date::date,
  r.interview_date::date,
  r.video_call_date::timestamp with time zone,
  r.passport_tracking_code::text,
  r.no_form_required::boolean,
  r.observacoes_gerais::text,
  r.notes::text,
  r.status::text,
  r.is_locked::boolean,
  r.is_completed::boolean,
  r.legacy_import::boolean,
  r.legacy_import_batch::text,
  r.stage_ds160_completed::boolean,
  r.stage_fee_generated::boolean,
  r.stage_fee_paid::boolean,
  r.stage_dates_scheduled::boolean,
  r.stage_video_call_scheduled::boolean,
  r.stage_video_call_done::boolean,
  r.stage_interview_done::boolean,
  r.stage_passport_returned::boolean,
  r.stage_feedback_sent::boolean,
  r.stage_feedback_answered::boolean,
  r.stage_feedback_posted::boolean,
  r.stage_ready_to_archive::boolean,
  NULL,
  now(),
  now()
FROM import_rows r
WHERE NOT EXISTS (
  SELECT 1
  FROM public.clients c
  WHERE regexp_replace(coalesce(c.cpf, ''), '\\D', '', 'g') = r.cpf
);

